<?php
function cms_field(string $key,array $def,string $value,string $prefix,array $media): void {
 [$label,$type]=$def;$id=$prefix.'-'.$key;
 if($type==='checkbox'){?><label class="check-field" for="<?= e($id) ?>"><input id="<?= e($id) ?>" type="checkbox" name="<?= e($key) ?>" value="1" <?= $value==='1'?'checked':'' ?>><span><?= e($label) ?></span></label><?php return;}
 ?><label class="field <?= $type==='textarea'?'wide':'' ?>" for="<?= e($id) ?>"><span><?= e($label) ?></span><?php
 if($type==='textarea'){?><textarea id="<?= e($id) ?>" name="<?= e($key) ?>" rows="4" maxlength="20000"><?= e($value) ?></textarea><?php }
 elseif($type==='select'){?><select id="<?= e($id) ?>" name="<?= e($key) ?>"><?php foreach($def[3] as $k=>$v): ?><option value="<?= e($k) ?>" <?= $value===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select><?php }
 elseif(in_array($type,['image','video','audio','pdf'],true)){?><select id="<?= e($id) ?>" name="<?= e($key) ?>" <?= $type==='image'?'data-image-select':'' ?>><option value="">None</option><?php foreach($media as $m): if(!($type==='pdf'?$m['mime']==='application/pdf':str_starts_with($m['mime'],$type.'/')))continue; ?><option value="<?= e($m['path']) ?>" <?= $value===$m['path']?'selected':'' ?>><?= e($m['title']) ?></option><?php endforeach; ?></select><?php if($type==='image'): ?><img class="field-image" src="<?= e($value?:'/assets/logo.png') ?>" alt="Selected image preview" <?= !$value?'hidden':'' ?>><?php endif; ?><span class="direct-media-upload"><span>Upload <?= e($type) ?> here</span><input type="file" form="studio-upload-only" data-direct-media data-module="<?= e(is_string($_GET['section']??null)?$_GET['section']:'event') ?>" data-kind="<?= e($type) ?>" accept="<?= $type==='pdf'?'application/pdf':e($type.'/*') ?>"></span><small data-upload-status role="status">New uploads also appear in the shared media library and Gallery photo choices.</small><?php }
 elseif($type==='price'){?><input id="<?= e($id) ?>" name="<?= e($key) ?>" type="number" value="<?= e($value) ?>" min="0" max="999999.99" step="0.01" required><small>₹0 means free; paid entry starts at ₹1. Used for standard entry when no custom ticket types are added. New checkouts use the latest saved fee.</small><?php }
 else{?><input id="<?= e($id) ?>" name="<?= e($key) ?>" type="<?= e($type) ?>" value="<?= e($value) ?>" <?= $type==='number'?'min="10" max="120"':($type==='datetime-local'?'':($type==='url'?'maxlength="2048"':'maxlength="500"')) ?>><?php }
 ?></label><?php
}
function cms_hidden(string $action): void {
 echo csrf_field().'<input type="hidden" name="action" value="'.e($action).'">';
 global $studioEventId,$environment;
 if(!empty($studioEventId))echo '<input type="hidden" name="studio_event_id" value="'.(int)$studioEventId.'">';
 if(isset($environment))echo '<input type="hidden" name="studio_environment" value="'.e($environment).'">';
}
function az_price_fields(string $json,array $games=[],bool $showGames=false): void {
 $rows=json_decode($json,true)?:[]; ?>
<fieldset class="wide price-editor"><legend>Custom ticket types & pricing (optional)</legend><p class="help">Leave empty to use the event’s registration fee for standard entry. Custom rows override that default with their own fee and capacity. ₹0 means free; paid passes start at ₹1. Tickets become available when registration opens. Each row keeps its identity when edited.</p><div id="price-rows"><?php foreach($rows as $i=>$r)az_price_row((string)$i,$r,$games,$showGames); ?></div><button class="quiet-button" id="add-price" type="button">+ Add ticket type</button><template id="price-template"><?php az_price_row('INDEX',[],$games,$showGames); ?></template></fieldset>
<?php }
function az_price_row(string $index,array $r,array $games=[],bool $showGames=false): void { ?>
<div class="price-row"><input type="hidden" name="ticket[<?= e($index) ?>][id]" value="<?= e($r['id']??'') ?>"><label class="field"><span>Ticket name</span><input name="ticket[<?= e($index) ?>][label]" value="<?= e($r['label']??'') ?>" maxlength="80" required></label><label class="field"><span>Price (INR)</span><input name="ticket[<?= e($index) ?>][price]" type="number" min="0" max="999999.99" step="0.01" value="<?= isset($r['price'])?number_format($r['price']/100,2,'.',''):'0.00' ?>" required></label><label class="field"><span>Capacity (0 = unlimited)</span><input name="ticket[<?= e($index) ?>][capacity]" type="number" min="0" max="1000000" value="<?= (int)($r['capacity']??0) ?>" required></label><?php if($showGames): ?><label class="field"><span>Game (optional)</span><select name="ticket[<?= e($index) ?>][game]"><option value="">Shared pass / no game</option><?php foreach($games as $game): ?><option value="<?= e($game['id']) ?>" <?= ($r['game']??'')===$game['id']?'selected':'' ?>><?= e($game['label']) ?></option><?php endforeach; ?></select></label><?php else: ?><input type="hidden" name="ticket[<?= e($index) ?>][game]" value=""><?php endif; ?><label class="check-field"><input type="checkbox" name="ticket[<?= e($index) ?>][active]" value="1" <?= ($r['active']??true)?'checked':'' ?>>On sale</label><button class="danger-button remove-price" type="button">Remove type</button></div>
<?php }
